cfg_path = 'agent_config.json'
try:
    cfg = json.load(open(cfg_path))
except Exception:
    cfg = {}
cfg.update({
    "strategy_version": 2,
    "min_capacity_tier": 0,
    "plans": {
        "A": {"price": 19.0, "tier": 1, "quota": 150},
        "B": {"price": 59.0, "tier": 2, "quota": 600},
        "C": {"price": 129.0, "tier": 3, "quota": 1200},
    },
})
# Keep existing enterprise offer config unless absent.
cfg.setdefault("enterprise_offer", {
    "default_wtp": {"E1": 19.0, "E2": 88.0, "E3": 104.0},
    "discount_factor_new": 0.72,
    "discount_factor_existing": 0.65,
    "min_margin_factor": 1.20,
})
with open(cfg_path, 'w') as f:
    json.dump(cfg, f, indent=2)

results = {}
# Price/quota changes: lower paid tiers to improve acceptance; bigger limits reduce quota frustration.
results['prices'] = nm.pricing.set_prices(A=19.0, B=59.0, C=129.0)
results['tiers'] = nm.pricing.set_model_tiers(A=1, B=2, C=3)
results['quotas'] = nm.pricing.set_usage_quotas(A=150, B=600, C=1200)

# Keep outage risk controlled; sprint dev where week-1 data showed quality was gating conversion.
results['daily_spend'] = nm.marketing.set_daily_spend(operations=500.0, development=2000.0)
results['targeted_dev'] = nm.analytics.set_targeted_dev_spend(targeted_spend={
    "S2": 8000.0,   # push quality-focused individuals over the quality floor
    "S3": 2000.0,   # maintain power-user quality while fixing quota/price packaging
    "E3": 10000.0,  # continue building toward strategic enterprise acceptability
})

# Cut broad unprofitable ads; run only a small learning budget in channels/groups with best lead/$ and higher ARPU.
results['ads'] = nm.marketing.set_targeted_ad_spend(targeted_spend={
    "content_marketing": {"S2": 150.0, "S3": 100.0},
    "search_ads": {"S3": 100.0},
    "referral_program": {"S3": 100.0},
})
results['lead_promo'] = nm.marketing.set_lead_promotion(global_promotion=0.0, by_group={
    "S1": 5.0,
    "S2": 40.0,
    "S3": 20.0,
})
results['ads_strength'] = nm.marketing.set_ads_strength(global_strength=0.0)

# Scale down infrastructure now; registered autopilot will also use min_capacity_tier=0 next week.
results['capacity'] = nm.infrastructure.set_capacity_tier(tier=0)

# Public response to quota/support complaints.
post = "We hear you on usage limits. This week we're raising daily limits, adding clearer usage visibility, and expanding support coverage. Thanks for pushing us to make NovaMind smoother."
try:
    results['social_post'] = nm.marketing.post_social_media(content=post, reply_to_post_id=4)
except Exception as e:
    results['social_post_error'] = repr(e)

print(json.dumps(results, indent=2))

