./novamind-operation python-c '
import novamind_api as nm, json
queries={
"subs_by_group_plan":"SELECT c.group_id,s.plan,COUNT(*) n, AVG(s.price) avg_price, SUM(CASE WHEN s.status=\"subscribed\" THEN 1 ELSE 0 END) active FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status=\"subscribed\" GROUP BY c.group_id,s.plan ORDER BY c.group_id,s.plan",
"customers_by_group":"SELECT group_id, COUNT(*) n, SUM(CASE WHEN customer_type=\"enterprise\" THEN 1 ELSE 0 END) ent FROM customers GROUP BY group_id ORDER BY group_id",
"ledger_by_day_type":"SELECT day, type, COUNT(*) cnt, SUM(amount) amount FROM ledger WHERE day>=7 GROUP BY day,type ORDER BY day,type",
"ledger_total":"SELECT type, COUNT(*) cnt, SUM(amount) amount FROM ledger GROUP BY type ORDER BY type",
"open_issues":"SELECT status, COUNT(*) n, AVG(severity) sev FROM issues GROUP BY status",
"recent_subs":"SELECT s.start_day,c.group_id,s.plan,s.price,COUNT(*) n FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.start_day>=7 GROUP BY s.start_day,c.group_id,s.plan,s.price ORDER BY s.start_day,c.group_id,s.plan",
"ad_ledger":"SELECT day, type, description, amount FROM ledger WHERE day>=7 AND (type LIKE \"%ad%\" OR description LIKE \"%ad%\" OR type LIKE \"%marketing%\") ORDER BY day LIMIT 100"
}
for name,q in queries.items():
 print("\n--",name)
 try:
  r=nm.query(q); print(json.dumps(r["rows"], indent=2)[:10000]);
  if r.get("warning"): print("WARN",r["warning"])
 except Exception as e: print("ERR",e)
'

