./novamind-operation python-c '
import novamind_api as nm, json
for t in ["config_history","config_overrides","service_day","ad_channel_leads","daily_usage","ads_revenue","research_projects","notifications","agent_social_media_posts","social_media_posts"]:
 print("\n--",t)
 try:
  rows=nm.query(f"SELECT * FROM {t} ORDER BY day DESC LIMIT 20")["rows"]
  print(json.dumps(rows, indent=2)[:12000])
 except Exception as e: print("ERR",e)
'

./novamind-operation python-c '
import novamind_api as nm, json
for gid in ["S1","S2","S3","E1","E2","E3"]:
 print("\n===",gid,"===")
 try:
  ins=nm.market.get_group_insights(gid)
  print(json.dumps(ins, indent=2)[:10000])
 except Exception as e: print("ERR",e)
'

