import novamind_api as nm
start_day=nm.vars.current_day; init_cash=nm.query('SELECT SUM(amount) cash FROM ledger')['rows'][0]['cash']
current=nm.query("SELECT c.group_id, s.plan, s.listed_price, s.billing_day_mod30 FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed'")['rows']
cap_tiers=[(1,200000,215),(2,800000,530),(3,2500000,1330),(4,8000000,4000),(5,25000000,10000)]
usage_est={'S1':91.1,'S2':231.5,'S3':570.6}
compute_per={'S1':{'A':0.025},'S2':{'A':0.036,'B':0.934,'C':1.55},'S3':{'A':0.014,'B':1.89,'C':5.93}}
mix=[('S2','A',0.08,19,0),('S2','B',0.86,79,39),('S2','C',0.05,159,119),('S3','B',0.01,79,39)]
def run(new_base=50,churn=0.06, policy='planned'):
 cash=init_cash; subs=[]; out={}
 for r in current:
  d=start_day+1; mod=r['billing_day_mod30']%30
  while d%30!=mod: d+=1
