arguments.content:
import novamind_api as nm, json

def q(sql): return nm.query(sql)['rows']
def pr(t, rows, lim=80):
 print('\n## '+t)
 if not rows: print('(none)'); return
 for r in rows[:lim]: print(r)
 if len(rows)>lim: print('... total', len(rows))
cur=nm.vars.current_day
print('day',cur)
pr('config overrides all', q("SELECT * FROM config_overrides ORDER BY id"), 300)
pr('config history recent', q(f"SELECT * FROM config_history WHERE day>{cur-28} ORDER BY day LIMIT 100"), 100)
print('\n## research projects API')
try: print(json.dumps(nm.research.list_research_projects(), indent=2))
except Exception as e: print('ERR',e)
pr('research_projects table', q("SELECT * FROM research_projects ORDER BY tier,start_day"), 100)
print('\n## social posts API')
try: print(json.dumps(nm.analytics.get_social_posts(days=21, limit=80), indent=2)[:16000])
except Exception as e: print('ERR',e)
pr('social table recent raw', q(f"SELECT * FROM social_media_posts WHERE day>{cur-21} ORDER BY day, post_id LIMIT 120"), 120)
pr('agent posts', q(f"SELECT * FROM agent_social_media_posts WHERE day>{cur-35} ORDER BY day"), 100)
print('\n## market overview')
try: print(json.dumps(nm.market.get_market_overview(), indent=2)[:12000])
except Exception as e: print('ERR',e)
for gid in ['S1','S2','S3','E1','E2','E3']:
 print(f'\n## insights {gid}')
 try: print(json.dumps(nm.market.get_group_insights(group_id=gid), indent=2)[:10000])
 except Exception as e: print('ERR',gid,e)
print('\n## cost info')
try: print(json.dumps(nm.infrastructure.get_cost_info(), indent=2))
except Exception as e: print('ERR', e)
pr('active billing mods revenue', q("SELECT billing_day_mod30, COUNT(*) n, ROUND(SUM(effective_price*seat_count),2) revenue FROM subscriptions WHERE status='subscribed' GROUP BY billing_day_mod30 ORDER BY billing_day_mod30"), 50)
pr('active subs effective price dist', q("SELECT plan, effective_price, COUNT(*) n FROM subscriptions WHERE status='subscribed' GROUP BY plan,effective_price ORDER BY plan,effective_price"),100)
pr('created last7 aggregate', q(f"SELECT c.created_day,c.group_id,c.acquisition_source,s.status,COUNT(*) n FROM customers c LEFT JOIN subscriptions s USING(customer_id) WHERE c.created_day>{cur-7} AND c.created_day<={cur} GROUP BY c.created_day,c.group_id,c.acquisition_source,s.status ORDER BY c.created_day,c.group_id,c.acquisition_source,s.status"),200)
# payment join using parsed customer id in note? SQLite funcs available? substr after last space maybe.
pr('payments last7 by group/plan/acq amount', q(f"""
WITH p AS (
 SELECT day,amount, CAST(SUBSTR(note, LENGTH('Subscription payment from customer ')+1) AS INTEGER) customer_id FROM ledger WHERE category='subscription_payment' AND day>{cur-7} AND day<={cur}
)
SELECT p.day,c.group_id,c.acquisition_source,s.plan,s.status,COUNT(*) n,ROUND(SUM(p.amount),2) amt FROM p JOIN customers c ON p.customer_id=c.customer_id JOIN subscriptions s ON s.customer_id=c.customer_id GROUP BY p.day,c.group_id,c.acquisition_source,s.plan,s.status ORDER BY p.day,c.group_id,c.acquisition_source,s.plan,s.status
"""),300)
pr('payments next 14 due by billing_day', q(f"""
SELECT ((billing_day_mod30 - ({cur+1}%30) + 30) % 30) days_until, billing_day_mod30, COUNT(*) n, ROUND(SUM(effective_price*seat_count),2) gross_renewal
FROM subscriptions WHERE status='subscribed' GROUP BY billing_day_mod30 ORDER BY days_until LIMIT 30
"""),50)

