import novamind_api as nm, math
cur=nm.vars.current_day
rows=nm.query("SELECT start_day, COUNT(*) n, SUM(effective_price*seat_count) rev FROM subscriptions WHERE status='subscribed' GROUP BY start_day ORDER BY start_day")['rows']
b={}
for r in rows:
 d=int(r['start_day']); n=int(r['n']); rev=float(r['rev'] or 0)
 nb=d+30
 while nb<=cur: nb+=30
 if nb<=cur+182:
  b.setdefault(nb,[0,0.0]); b[nb][0]+=n; b[nb][1]+=rev
print('days', cur, 'active rows groups', len(rows))
for d in sorted(b): print(d,b[d])
for horizon in [7,28,84,182]:
 print('h',horizon,'n',sum(v[0] for d,v in b.items() if cur<d<=cur+horizon),'rev',sum(v[1] for d,v in b.items() if cur<d<=cur+horizon))
print('MRR', nm.query("SELECT COUNT(*) n,SUM(effective_price*seat_count) rev FROM subscriptions WHERE status='subscribed'")['rows'])

