./novamind-operation python-c "import novamind_api as nm, re, json; cur=nm.vars.current_day; pays=nm.query(f"SELECT day,amount,note FROM ledger WHERE category='subscription_payment' AND day>{cur-7} AND day<={cur}")['rows']; ids=[]; pay_by={};
for p in pays:
    m=re.search(r'customer (\d+)', p['note']);
    if m: pay_by[int(m.group(1))]=pay_by.get(int(m.group(1)),0)+float(p['amount']);
rows=nm.query(f"SELECT c.customer_id,c.created_day,c.group_id,c.acquisition_source,s.status,s.plan,s.effective_price,s.seat_count FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.created_day>{cur-7} AND c.created_day<={cur} AND c.customer_type!='large' AND s.status='subscribed'")['rows'];
from collections import defaultdict
agg=defaultdict(lambda:[0,0,0]);
for r in rows:
    key=(r['group_id'],r['acquisition_source']); agg[key][0]+=1; agg[key][1]+=float(r['effective_price'])*int(r['seat_count']); agg[key][2]+=pay_by.get(int(r['customer_id']),0);
print('new subs',len(rows),'new mrr',sum(a[1] for a in agg.values()),'first cash matched',sum(a[2] for a in agg.values()));
for k,a in sorted(agg.items(), key=lambda kv:-kv[1][0]): print(k,a,'avg_mrr',a[1]/a[0],'avg_cash',a[2]/a[0])
"

