import json
import novamind_api as nm

# Day 77 actions: respond to competitor quality shock + support drag while protecting cash.
results = {}

def call(name, fn, *args, **kwargs):
    try:
        res = fn(*args, **kwargs)
        results[name] = res
        print(f"{name}: {json.dumps(res, default=str)[:1000]}")
        return res
    except Exception as e:
        results[name] = {"error": repr(e)}
        print(f"{name} ERROR: {e!r}")
        return None

# Re-price new customers to reduce quality-price friction after large competitor expectation shocks.
call('set_prices', nm.pricing.set_prices, A=25.0, B=89.0, C=179.0)
# Make C a true premium/high-quality safe harbor; keep B tier3 to avoid a $45k/week compute step-up until we see response.
call('set_model_tiers', nm.pricing.set_model_tiers, A=1, B=3, C=5)
call('set_usage_quotas', nm.pricing.set_usage_quotas, A=400, B=1500, C=4000)
call('set_capacity_tier', nm.infrastructure.set_capacity_tier, tier=4)

# Keep no in-app ads; continue only proven S2 content ads, cut unproductive S3 search and E3 LinkedIn tests.
call('set_ads_strength', nm.marketing.set_ads_strength, global_strength=0.0)
call('set_targeted_ad_spend', nm.marketing.set_targeted_ad_spend, targeted_spend={
    'content_marketing': {'S2': 2700.0}
})
# Lead promo: restore S2 to $20 to recover conversion while using list price B=$89 for recurring value.
call('set_lead_promotion', nm.marketing.set_lead_promotion, global_promotion=0.0, by_group={'S1': 5.0, 'S2': 20.0, 'S3': 20.0})
# No broad recurring promotion yet; preserve existing MRR and wait to see if price list + C quality + dev stabilize churn.
call('set_promotion', nm.pricing.set_promotion, global_promotion=0.0, by_group={}, by_group_plan={})

# Keep global spend, increase S2-specific support/dev. Ops group targeting is legacy-only in installed API.
call('set_daily_spend', nm.marketing.set_daily_spend, operations=1500.0, development=1200.0)
call('set_targeted_ops_spend', nm.analytics.set_targeted_ops_spend, targeted_spend={'S2': 8000.0, 'S3': 200.0})
call('set_targeted_dev_spend', nm.analytics.set_targeted_dev_spend, targeted_spend={'S2': 2500.0, 'S3': 300.0})

# Public response: acknowledge the support issue and competitor quality bar without overclaiming resolution.
post = "Rachel/David are right: product ROI is fragile when support bounces tickets. This week S2 resolved 8,178 issues, but 40 cases >48h/30 >7d is unacceptable. We’re putting more S2 support on the queue and shipping quality hardening after the new competitor benchmarks."
call('post_social_media', nm.marketing.post_social_media, content=post, reply_to_post_id=162)

# Update persistent agent config for future autopilot/CEO memory.
config = {
  'strategy_version': 12,
  'min_capacity_tier': 4,
  'plans': {
    'A': {'price': 25.0, 'tier': 1, 'quota': 400},
    'B': {'price': 89.0, 'tier': 3, 'quota': 1500},
    'C': {'price': 179.0, 'tier': 5, 'quota': 4000}
  },
  'spend': {
    'global_ops': 1500.0,
    'global_dev': 1200.0,
    'targeted_ops': {'S2': 8000.0, 'S3': 200.0},
    'targeted_dev': {'S2': 2500.0, 'S3': 300.0},
    'targeted_ads': {'content_marketing': {'S2': 2700.0}}
  },
  'promos': {
    'lead_by_group': {'S1': 5.0, 'S2': 20.0, 'S3': 20.0},
    'ongoing': {}
  },
  'enterprise_offer': {
    'default_wtp': {'E1': 19.0, 'E2': 88.0, 'E3': 104.0},
    'discount_factor_new': 0.72,
    'discount_factor_existing': 0.65,
    'min_margin_factor': 1.2,
    'day70_E3_counter_floor': {'B': 39.0, 'C': 49.0}
  },
  'notes': 'Day77: competitor shocks collapsed S2 conversion; reverted new B to $89, S2 lead promo $20, upgraded C to tier5, cut unproductive S3/E3 ads, raised S2 ops/dev. Installed ops API only accepts targeted_spend={group: amount}.'
}
with open('agent_config.json', 'w') as f:
    json.dump(config, f, indent=2)
print('agent_config.json updated')

