import json
import novamind_api as nm

results = {}
# Keep proven prices/quotas, but improve Plan A quality for S2 lost-A bottleneck while avoiding costly B tier4.
results['prices'] = nm.pricing.set_prices(A=25, B=89, C=179)
results['tiers'] = nm.pricing.set_model_tiers(A=2, B=3, C=5)
results['quotas'] = nm.pricing.set_usage_quotas(A=400, B=1500, C=4000)
results['capacity'] = nm.infrastructure.set_capacity_tier(tier=4)

# No in-app ads; paid acquisition remains S2 content but modestly scaled because unit economics stayed positive.
results['ads_strength'] = nm.marketing.set_ads_strength(global_strength=0.0, by_group={})
results['targeted_ads'] = nm.marketing.set_targeted_ad_spend(targeted_spend={"content_marketing": {"S2": 3000.0}})

# Slightly larger S2 first-month discount to reduce price-quality friction after competitor shocks; no ongoing discount.
results['lead_promo'] = nm.marketing.set_lead_promotion(global_promotion=0.0, by_group={"S1": 5.0, "S2": 25.0, "S3": 20.0})
results['ongoing_promo'] = nm.pricing.set_promotion(global_promotion=0.0, by_group={}, by_group_plan={})

# Keep global resilience and add another one-week S2 support surge; increase S2 dev to rebuild quality faster.
results['daily_spend'] = nm.marketing.set_daily_spend(operations=1500.0, development=1200.0)
results['targeted_ops'] = nm.analytics.set_targeted_ops_spend(targeted_spend={"S2": 10000.0, "S3": 200.0})
results['targeted_dev'] = nm.analytics.set_targeted_dev_spend(targeted_spend={"S2": 3500.0, "S3": 300.0})

# Social response: acknowledge support concern while emphasizing concrete operational fix.
post = "Dr. Foster/Rachel: fair critique. Great synthesis only matters if support owns the fix. We’ve moved S2 API/healthcare tickets to named owners, added another support surge this week, and are tracking >48h tickets daily. Product quality stays high; support must match it."
try:
    results['social'] = nm.marketing.post_social_media(content=post, reply_to_post_id=176)
except Exception as e:
    results['social_error'] = repr(e)

# Update autopilot config used at start of future weeks.
cfg = {
  "strategy_version": 13,
  "min_capacity_tier": 4,
