./novamind-operation python-c "import novamind_api as nm; D=nm.vars.current_day; mods=[(D+i)%30 for i in range(1,8)]; rows=nm.query(f'''SELECT s.start_day, s.billing_day_mod30 mod, c.group_id, s.plan, COUNT(*) n, SUM(s.effective_price*s.seat_count) rev, SUM(s.listed_price*s.seat_count) list FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' AND s.billing_day_mod30 IN ({','.join(map(str,mods))}) GROUP BY s.start_day, s.billing_day_mod30, c.group_id, s.plan ORDER BY s.billing_day_mod30, s.start_day, c.group_id, s.plan''')['rows'];
for r in rows[:200]: print(r)
print('nrows',len(rows));"

