            FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id
            WHERE s.status='subscribed'
            GROUP BY c.group_id, s.plan
        """)
        if not rows:
            nm.infrastructure.set_capacity_tier(tier=int(cfg.get('min_capacity_tier', 1)))
            return
        usage_cache = {}
        total_usage = 0.0
        for r in rows:
            gid = r['group_id']; seats = float(r.get('seats') or 0)
            if gid not in usage_cache:
                ins = get_insights_safe(gid)
                est = (ins or {}).get('estimates', {})
                usage_cache[gid] = float(est.get('usage_volume') or 150.0)
            total_usage += seats * usage_cache[gid]
        target = total_usage * 1.35 + 25000
        min_tier = int(cfg.get('min_capacity_tier', 1))
        chosen = 7
        for tier, (cap, cost) in CAPACITY.items():
            if tier >= min_tier and cap >= target:
                chosen = tier; break
        nm.infrastructure.set_capacity_tier(tier=chosen)
        if getattr(nm.vars, 'current_day', 0) % 7 == 0:
            log(f"capacity tier {chosen} for estimated usage {total_usage:.0f}/day")
    except Exception as e:
        log('capacity scaling error: '+repr(e)+' '+traceback.format_exc()[:300])

def enterprise_offers_for(gid, thread_type, seat_count, cfg):
    plans = cfg.get('plans', {})
    # Get current group WTP and usage estimates; fallback to named initial groups.
    ins = get_insights_safe(gid)
    est = (ins or {}).get('estimates', {})
    defaults = cfg.get('enterprise_offer', {}).get('default_wtp', {})
    wtp = float(est.get('willingness_to_pay') or defaults.get(gid, 75.0))
    usage = float(est.get('usage_volume') or (52.0 if gid == 'E1' else 160.0))
    # More aggressive discounts for churn prevention / existing customers.
    eo = cfg.get('enterprise_offer', {})
    disc = float(eo.get('discount_factor_existing' if thread_type in ('churn_prevention','renegotiation','renewal','plan_change') else 'discount_factor_new', 0.72))
    margin_factor = float(eo.get('min_margin_factor', 1.20))
    # price floor from compute cost + small support margin.
    def monthly_cost(plan):
        tier = int(plans.get(plan, {}).get('tier', {'A':1,'B':2,'C':3}[plan]))
        return usage * MODEL_COST.get(tier, 0.006) * 30.0
    offers = []
    # Prefer C for quality, B for cheaper compute. Avoid A for high-quality enterprise unless E1/low WTP.
    for plan, frac in [('B', disc*0.88), ('C', disc*1.00)]:
        cost = monthly_cost(plan)
        price = max(wtp * frac, cost * margin_factor + (2.0 if plan == 'B' else 4.0))
        # Keep below nominal WTP unless cost floor requires otherwise; if cost floor is above WTP, still offer near cost.
        if price < wtp * 0.98:
            price = min(price, wtp * 0.96)
        price = max(1.0, round(price, 2))
        offers.append([plan, price])
    if gid == 'E1' or wtp < 35:
        cost = monthly_cost('A')
        price = max(wtp * disc * 0.70, cost * margin_factor + 1.0)
        price = min(max(1.0, price), max(1.0, wtp * 0.90))
        offers.insert(0, ['A', round(price, 2)])
    # Deduplicate/limit to 3, ensure price nondecreasing roughly by plan quality.
    out = []
    seen = set()
    for p in offers:
        if p[0] not in seen and len(out) < 3:
            out.append(p); seen.add(p[0])
    return out

def respond_enterprise(cfg):
    try:
        # Need latest row in each open customer/thread_type conversation; if it is from the customer, we owe a response.
        # The public enterprise_turns table has no thread_id column, so group by customer_id + thread_type.
        rows = q("""
            WITH latest AS (
              SELECT customer_id, thread_type, MAX(message_id) AS mid
              FROM enterprise_turns
              WHERE closed=0
              GROUP BY customer_id, thread_type
            )
            SELECT t.message_id, t.customer_id, t.thread_type, t.turn_number,
                   t.sender, t.message_text, t.day, t.seat_count, c.group_id
            FROM enterprise_turns t
            JOIN latest l ON t.customer_id=l.customer_id AND t.thread_type=l.thread_type AND t.message_id=l.mid
            JOIN customers c ON c.customer_id=t.customer_id
            WHERE t.sender IN ('customer','system')
            ORDER BY t.day ASC, t.message_id ASC
            LIMIT 200
        """)
        if not rows:
            return
        deals = []
        for r in rows:
            gid = r.get('group_id') or ''
            if not (gid.startswith('E') or gid.startswith('D_E')):
                continue
            offers = enterprise_offers_for(gid, r.get('thread_type') or 'new_lead', r.get('seat_count') or 1, cfg)
            if offers:
                deals.append([int(r['customer_id']), offers])
        if deals:
            res = nm.enterprise.send_enterprise_deal(deals=deals)
            log(f"sent {len(deals)} enterprise deal replies: {str(res)[:500]}")
    except Exception as e:
        log('enterprise response error: '+repr(e)+' '+traceback.format_exc()[:500])

try:
    cfg = load_cfg()
    respond_enterprise(cfg)
    scale_capacity(cfg)
except Exception as e:
    log('autopilot top-level error: '+repr(e)+' '+traceback.format_exc()[:500])

