for sql in [
'''SELECT i.group_id, CASE WHEN s.customer_id IS NULL THEN 'inactive' ELSE 'active' END as sub_status, COUNT(*) open, SUM(CASE WHEN i.days_open=0 THEN 1 ELSE 0 END) age0, SUM(CASE WHEN i.days_open=1 THEN 1 ELSE 0 END) age1, SUM(CASE WHEN i.days_open=2 THEN 1 ELSE 0 END) age2, SUM(CASE WHEN i.days_open BETWEEN 3 AND 6 THEN 1 ELSE 0 END) age3_6, SUM(CASE WHEN i.days_open>=7 THEN 1 ELSE 0 END) age7p, MAX(i.days_open) max_age FROM issues i LEFT JOIN subscriptions s ON s.customer_id=i.customer_id AND s.status='subscribed' WHERE i.status='open' GROUP BY i.group_id, sub_status ORDER BY i.group_id, sub_status''',
'''SELECT c.group_id, s.plan, COUNT(*) n, SUM(CASE WHEN c.created_day>=113 THEN 1 ELSE 0 END) neww FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' GROUP BY c.group_id,s.plan ORDER BY c.group_id,s.plan'''
]:
 print('---');
 for r in q(sql): print(r)
"

