Q= 
SELECT c.group_id, i.status, (140 - i.created_day) age, COUNT(*) n
FROM issues i JOIN customers c ON i.customer_id=c.customer_id
WHERE i.status!='resolved'
GROUP BY c.group_id,i.status,age ORDER BY c.group_id,age DESC


