    r=nm.query("SELECT SUM(amount) cash FROM ledger")['rows'][0]['cash']
    print('cash ledger', r)
except Exception as e: print('cash err',e)
# settings via config tables? Try overviews
for name, func in [('market_overview', nm.market.get_market_overview), ('cost_info', nm.infrastructure.get_cost_info), ('research', nm.research.list_research_projects)]:
    print('\n===',name,'===')
    try:
        x=func();
        if isinstance(x,(dict,list)):
            print(json.dumps(x, indent=2, default=str)[:5000])
        else: print(x)
    except Exception as e: print('ERR',e)

# social posts
print('\n=== social posts ===')
try:
    posts=nm.analytics.get_social_posts(days=14,limit=100)
    print(json.dumps(posts, indent=2, default=str)[:20000])
except Exception as e: print('social err',e)

queries={
'ledger_7': "SELECT day, category, subcategory, COUNT(*) n, SUM(amount) amt FROM ledger WHERE day > {d}-7 GROUP BY day, category, subcategory ORDER BY day, category, subcategory".format(d=day),
'ledger_30_cat': "SELECT category, subcategory, COUNT(*) n, SUM(amount) amt FROM ledger WHERE day > {d}-30 GROUP BY category, subcategory ORDER BY category, subcategory".format(d=day),
'active_by_group_plan': "SELECT c.group_id, s.plan, COUNT(*) n, SUM(s.effective_price) mrr, AVG(s.effective_price) arpu, AVG(c.daily_usage) avg_usage FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' GROUP BY c.group_id,s.plan ORDER BY c.group_id,s.plan",
'active_by_group': "SELECT c.group_id, COUNT(*) n, SUM(s.effective_price) mrr, AVG(s.effective_price) arpu, SUM(COALESCE(c.seats,1)) seats, AVG(c.satisfaction) sat, AVG(c.quality_requirement) qreq, AVG(c.daily_usage) usage FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' GROUP BY c.group_id ORDER BY n DESC",
'new_customers_7': "SELECT c.group_id, c.customer_type, COUNT(*) n FROM customers c WHERE c.created_day > {d}-7 GROUP BY c.group_id,c.customer_type ORDER BY n DESC".format(d=day),
'new_subs_7_by_group_plan': "SELECT c.group_id, s.plan, COUNT(*) n, SUM(s.effective_price) mrr, AVG(s.effective_price) arpu, AVG(s.listed_price) avg_list, AVG(s.promotion) avg_promo, MIN(s.start_day) min_start, MAX(s.start_day) max_start FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.start_day > {d}-7 AND s.status='subscribed' GROUP BY c.group_id,s.plan ORDER BY c.group_id,s.plan".format(d=day),
'cancellations_7': "SELECT c.group_id, s.plan, COUNT(*) n, AVG(s.effective_price) arpu, AVG(s.cancel_day-s.start_day) tenure FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='cancelled' AND s.cancel_day > {d}-7 GROUP BY c.group_id,s.plan ORDER BY n DESC".format(d=day),
'enterprise_open': "SELECT * FROM enterprise_turns WHERE closed=0 ORDER BY day DESC, message_id DESC LIMIT 100",
'enterprise_recent': "SELECT * FROM enterprise_turns ORDER BY day DESC, message_id DESC LIMIT 100",
'issues': "SELECT status, COUNT(*) n, AVG(created_day) avg_created, AVG(resolved_day-created_day) avg_resolve FROM customer_issues GROUP BY status" if False else "SELECT 1 one",
'ad_attribution_7': "SELECT day, group_id, channel, COUNT(*) leads, SUM(CASE WHEN became_subscriber THEN 1 ELSE 0 END) subs FROM marketing_leads WHERE day > {d}-7 GROUP BY day,group_id,channel ORDER BY day,group_id,channel".format(d=day),
}
# schema guesses may fail
for name,q in queries.items():
    print('\n=== QUERY', name,'===')
    try:
        res=nm.query(q)
        print('rows',len(res['rows']), 'truncated', res.get('truncated'))
        for row in res['rows'][:200]: print(row)
    except Exception as e:
        print('ERR',e)
