arguments.content:
import json
import novamind_api as nm

def q(sql):
 r=nm.query(sql)['rows'];
 for row in r: print(row)
 return r
print('NEED RESPONSE')
q('''WITH latest AS (SELECT customer_id, MAX(message_id) max_mid FROM enterprise_turns WHERE closed=0 GROUP BY customer_id)
SELECT et.customer_id,c.group_id,et.day,et.seat_count,c.company_size_descriptor,c.company_culture,c.company_decision_style,c.company_primary_concern,c.persona_description,c.email
FROM latest l JOIN enterprise_turns et ON et.message_id=l.max_mid JOIN customers c ON c.customer_id=et.customer_id LEFT JOIN subscriptions s ON s.customer_id=et.customer_id
WHERE et.closed=0 AND et.sender!='agent' AND (s.status IS NULL OR s.status!='lost') ORDER BY et.day, et.customer_id''')
print('INSIGHTS')
for gid in ['E1','E2','E3','D_E02','D_E07','D_E08','D_E09','D_E01','D_E03','D_E10']:
    try:
        print('\n--',gid)
        print(json.dumps(nm.market.get_group_insights(gid), indent=2)[:5000])
    except Exception as e: print('ERR',gid,e)

