./novamind-operation python-c "import novamind_api as nm, json, collections; promos=set(json.load(open('s2_retention_promos.json'))); mods=[(nm.vars.current_day+i)%30 for i in range(1,8)]; modstr=','.join(map(str,mods)); rows=[]; off=0; sql=f'''SELECT s.customer_id,s.billing_day_mod30 mod,s.plan,s.listed_price,s.status FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id=\'S2\' AND s.status=\'subscribed\' AND s.billing_day_mod30 IN ({modstr}) AND s.plan IN (\'B\',\'C\') AND s.listed_price>=139 ORDER BY s.customer_id''';
while True:
 r=nm.query(sql+f' LIMIT 5000 OFFSET {off}')['rows']; rows+=r
 if len(r)<5000: break
 off+=5000
ctr=collections.Counter((r['plan'],round(r['listed_price']), str(r['customer_id']) in promos) for r in rows); print('mods',mods,'rows',len(rows));
for k,v in sorted(ctr.items()): print(k,v)"

