WITH days(day) AS (SELECT 239 UNION SELECT 240 UNION SELECT 241 UNION SELECT 242 UNION SELECT 243 UNION SELECT 244 UNION SELECT 245 UNION SELECT 246 UNION SELECT 247 UNION SELECT 248 UNION SELECT 249 UNION SELECT 250 UNION SELECT 251 UNION SELECT 252),
created AS (
 SELECT created_day day, group_id, COUNT(*) leads FROM customers WHERE customer_type='small' AND created_day>238 GROUP BY created_day, group_id
), subd AS (
 SELECT s.start_day day, c.group_id, COUNT(*) subs, SUM(s.effective_price) mrr FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.customer_type='small' AND s.start_day>238 GROUP BY s.start_day,c.group_id
), canc AS (
 SELECT s.end_day day, c.group_id, COUNT(*) cancels, SUM(s.effective_price) lost_mrr FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.customer_type='small' AND s.status='cancelled' AND s.end_day>238 GROUP BY s.end_day,c.group_id
)
SELECT d.day, COALESCE(created.group_id, subd.group_id, canc.group_id) group_id, COALESCE(leads,0) leads, COALESCE(subs,0) subs, COALESCE(mrr,0) new_mrr, COALESCE(cancels,0) cancels, COALESCE(lost_mrr,0) lost_mrr
FROM days d LEFT JOIN created ON created.day=d.day LEFT JOIN subd ON subd.day=d.day AND subd.group_id=created.group_id LEFT JOIN canc ON canc.day=d.day AND canc.group_id=COALESCE(created.group_id, subd.group_id)
WHERE COALESCE(created.group_id, subd.group_id, canc.group_id) IS NOT NULL
UNION
SELECT d.day, COALESCE(created.group_id, subd.group_id, canc.group_id) group_id, COALESCE(leads,0), COALESCE(subs,0), COALESCE(mrr,0), COALESCE(cancels,0), COALESCE(lost_mrr,0)
FROM days d LEFT JOIN subd ON subd.day=d.day LEFT JOIN created ON created.day=d.day AND created.group_id=subd.group_id LEFT JOIN canc ON canc.day=d.day AND canc.group_id=COALESCE(created.group_id, subd.group_id)
WHERE COALESCE(created.group_id, subd.group_id, canc.group_id) IS NOT NULL
UNION
SELECT d.day, COALESCE(created.group_id, subd.group_id, canc.group_id) group_id, COALESCE(leads,0), COALESCE(subs,0), COALESCE(mrr,0), COALESCE(cancels,0), COALESCE(lost_mrr,0)
FROM days d LEFT JOIN canc ON canc.day=d.day LEFT JOIN created ON created.day=d.day AND created.group_id=canc.group_id LEFT JOIN subd ON subd.day=d.day AND subd.group_id=COALESCE(created.group_id, canc.group_id)
WHERE COALESCE(created.group_id, subd.group_id, canc.group_id) IS NOT NULL
ORDER BY day, group_id


