arguments.command:
./novamind-operation python-c "import novamind_api as nm; day=nm.vars.current_day; prev=day-7; queries=[('new subscription rows by status',f\"SELECT s.status,c.group_id,COUNT(*) n,ROUND(SUM(s.effective_price),2) mrr FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.customer_type='small' AND s.start_day>{prev} AND s.start_day<={day} GROUP BY s.status,c.group_id ORDER BY c.group_id,s.status\"),('created customers by status',f\"SELECT s.status,c.group_id,COUNT(*) n FROM customers c LEFT JOIN subscriptions s USING(customer_id) WHERE c.customer_type='small' AND c.created_day>{prev} AND c.created_day<={day} GROUP BY s.status,c.group_id ORDER BY c.group_id,s.status\"),('paid rows by status',f\"SELECT s.status,COUNT(*) n,ROUND(SUM(s.effective_price),2) mrr FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='S2' AND c.acquisition_source='content_marketing' AND s.start_day>{prev} AND s.start_day<={day} GROUP BY s.status\")];
for name,sql in queries:
 print('\n##',name); print(nm.query(sql).get('rows'))"

