arguments.command:
./novamind-operation python-c "import novamind_api as nm; day=nm.vars.current_day; prev=day-7; mods=','.join(str(d%30) for d in range(prev+1,day+1));
for g in ['D_S07','S3','D_S04']:
 print('\n',g); sql=f'''SELECT s.plan,ROUND(s.listed_price,0) listed,ROUND(s.promotion,0) promo,ROUND(s.effective_price,0) eff,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) active,SUM(CASE WHEN s.status='cancelled' AND s.end_day>{prev} THEN 1 ELSE 0 END) cancels,ROUND(1.0*SUM(CASE WHEN s.status='cancelled' AND s.end_day>{prev} THEN 1 ELSE 0 END)/NULLIF(SUM(CASE WHEN s.status='subscribed' OR (s.status='cancelled' AND s.end_day>{prev}) THEN 1 ELSE 0 END),0),3) churn FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='{g}' AND s.billing_day_mod30 IN ({mods}) AND (s.status='subscribed' OR (s.status='cancelled' AND s.end_day>{prev})) GROUP BY s.plan,ROUND(s.listed_price,0),ROUND(s.promotion,0),ROUND(s.effective_price,0) ORDER BY s.plan,eff''';
 for r in nm.query(sql).get('rows'): print(r)"

