import json, novamind_api as nm
DAY=nm.vars.current_day
print('DAY',DAY)

def q(sql):
    r=nm.query(sql)
    if r.get('warning'): print('WARNING', r['warning'])
    return r['rows']

def show(title, rows, n=100):
    print('\n##',title)
    for row in rows[:n]: print(row)
    if len(rows)>n: print('... total',len(rows))

print('\n## Cost info')
try: print(json.dumps(nm.infrastructure.get_cost_info(), indent=2)[:8000])
except Exception as e: print('cost err',e)

print('\n## Research projects')
try: print(json.dumps(nm.research.list_research_projects(), indent=2)[:12000])
except Exception as e: print('research err',e)

print('\n## Market overview')
try: print(json.dumps(nm.market.get_market_overview(), indent=2)[:15000])
except Exception as e: print('market err',e)

for gid in ['S2','D_S07','S3','D_S02','D_S06','D_S08','S1']:
    print('\n## Insights',gid)
    try: print(json.dumps(nm.market.get_group_insights(group_id=gid), indent=2)[:12000])
    except Exception as e: print('insights err',gid,e)

print('\n## Social posts last 14 API')
try: print(json.dumps(nm.analytics.get_social_posts(days=14, limit=120), indent=2)[:24000])
except Exception as e: print('social err',e)
show('Social posts SQL recent', q(f"SELECT * FROM social_media_posts WHERE day>{DAY-14} ORDER BY day DESC, post_id DESC LIMIT 120"), n=120)
show('Agent posts recent', q("SELECT * FROM agent_social_media_posts ORDER BY day DESC LIMIT 20"), n=30)

show('Enterprise open threads latest per customer', q("""
WITH latest AS (
 SELECT customer_id, MAX(message_id) max_mid FROM enterprise_turns WHERE closed=0 GROUP BY customer_id
)
SELECT e.* FROM enterprise_turns e JOIN latest l ON e.customer_id=l.customer_id AND e.message_id=l.max_mid ORDER BY e.day DESC LIMIT 100
"""), n=100)
show('Enterprise all summary', q("SELECT closed, close_reason, sender, COUNT(*) n, MIN(day) min_day, MAX(day) max_day FROM enterprise_turns GROUP BY closed, close_reason, sender ORDER BY closed, close_reason, sender"), n=100)
show('Active enterprise subs', q("""
SELECT c.customer_id,c.group_id,c.email,s.plan,s.seat_count,s.listed_price,s.effective_price,s.status,s.start_day,s.end_day
FROM subscriptions s JOIN customers c USING(customer_id)
WHERE c.customer_type='large' ORDER BY s.status, s.start_day DESC LIMIT 200
"""), n=200)

# Days cash/revenue net table last 35
show('Daily net/rev/cost last 35', q(f"""
SELECT day,
 SUM(amount) net,
 SUM(CASE WHEN category='subscription_payment' THEN amount ELSE 0 END) rev,
 SUM(CASE WHEN category!='subscription_payment' THEN amount ELSE 0 END) costs,
 SUM(CASE WHEN category='operations' THEN amount ELSE 0 END) ops,
 SUM(CASE WHEN category='compute' THEN amount ELSE 0 END) compute,
 SUM(CASE WHEN category='advertising' THEN amount ELSE 0 END) ads,
 SUM(CASE WHEN category='development' THEN amount ELSE 0 END) dev,
 SUM(CASE WHEN category='capacity' THEN amount ELSE 0 END) cap,
 SUM(CASE WHEN category='lead_acquisition_cost' THEN amount ELSE 0 END) lead_cost
FROM ledger WHERE day>{DAY-35} AND day<= {DAY} GROUP BY day ORDER BY day
"""), n=40)

