import novamind_api as nm, re, collections
DAY=nm.vars.current_day
q=lambda sql: nm.query(sql)['rows']
ledger=[]; lastid=0
while True:
 rr=q(f"select id, day, amount, note from ledger where category='subscription_payment' and day>{DAY-7} and day<={DAY} and id>{lastid} order by id limit 5000")
 if not rr: break
 ledger.extend(rr); lastid=rr[-1]['id']
ids=[]
for r in ledger:
 m=re.search(r'customer (\d+)', r['note']);
 if m: ids.append(int(m.group(1)))
info={}
for i in range(0,len(ids),900):
 chunk=ids[i:i+900]
 for r in q("select s.customer_id,c.group_id,c.acquisition_source,s.status,s.plan,s.listed_price,s.promotion,s.effective_price,s.start_day,s.end_day,s.billing_day_mod30 from subscriptions s join customers c using(customer_id) where s.customer_id in (%s)"%(','.join(map(str,chunk)))):
  info[r['customer_id']]=r
agg=collections.defaultdict(lambda:[0,0.0])
for r in ledger:
 m=re.search(r'customer (\d+)', r['note']); cid=int(m.group(1))
 inf=info[cid]
 age=r['day']-inf['start_day']
 ageb='initial' if age<=1 else ('lt31' if age<31 else ('31-60' if age<61 else ('61-90' if age<91 else '90+')))
 k=(inf['group_id'],inf['acquisition_source'],inf['plan'],inf['listed_price'],r['amount'],ageb,inf['status'])
 agg[k][0]+=1; agg[k][1]+=r['amount']
for k,v in sorted(agg.items(), key=lambda kv: kv[1][1], reverse=True)[:100]: print(k,v)
print('\nB139 payments by age/source amount')
for k,v in sorted(agg.items()):
 if k[2]=='B' and k[3]==139.0: print(k,v)

import novamind_api as nm, json, collections
DAY=nm.vars.current_day
q=lambda sql: nm.query(sql)['rows']
settings=json.loads(q("select settings_json from config_overrides where setting_type='promotion' order by id desc limit 1")[0]['settings_json'])
bycust={int(k):float(v) for k,v in settings.get('by_customer',{}).items()}
rows=[]; last=0
