import novamind_api as nm, math, re
DAY=nm.vars.current_day
q=lambda sql: nm.query(sql)['rows']
print('DAY',DAY,'cash',q('select sum(amount) cash from ledger')[0]['cash'])

def promo_for(g,plan,lp,age,current_p=0):
    lp=float(lp); age=int(age)
    if g=='S2':
        if plan=='B' and lp>=139: return 100.0 if age<61 else 70.0
        if plan=='C' and lp>=259: return 80.0
        if plan=='A' and lp>=49: return 20.0
        if plan=='A' and lp in (25.0,29.0): return 5.0
        if plan=='A' and lp in (39.0,45.0): return 10.0
        return 0.0
    else:
        return float(current_p or 0)

def eff(g,plan,lp,age,current_p=0):
    return max(0.0,float(lp)-promo_for(g,plan,lp,age,current_p))
# Page all active
rows=[]; last=0
while True:
    rs=q(f"""select s.customer_id,c.group_id,s.plan,s.listed_price,s.promotion,s.effective_price,s.start_day,s.billing_day_mod30,s.seat_count
             from subscriptions s join customers c using(customer_id)
             where s.status='subscribed' and s.customer_id>{last} order by s.customer_id limit 5000""")
    if not rs: break
    rows += rs; last=rs[-1]['customer_id']
print('active rows',len(rows))
for horizon in [7,14,28,30,84,182]:
    due=0; field=0; n=0
    by={}
    maxoffset=horizon if horizon<30 else 29
    for r in rows:
        offset=(int(r['billing_day_mod30'])-(DAY%30)+30)%30
        if offset>=1 and offset<=maxoffset:
            age=DAY-int(r['start_day'])
            e=eff(r['group_id'],r['plan'],r['listed_price'],age,r['promotion'])*int(r['seat_count'])
            due += e; field += float(r['effective_price'])*int(r['seat_count']); n+=1
            key=(r['group_id'], r['plan'], float(r['listed_price']), promo_for(r['group_id'],r['plan'],r['listed_price'],age,r['promotion']), 'young' if age<61 else 'old')
            by[key]=by.get(key, [0,0.0])[0]+1, by.get(key,[0,0.0])[1]+e
    print('\nhorizon',horizon,'n',n,'adj_due',round(due,2),'field_due',round(field,2))
    for k,v in sorted(by.items(), key=lambda kv: kv[1][1], reverse=True)[:25]:
        print(k, v)
# Current adjusted MRR all active
mrr=0; field=0; bym={}
for r in rows:
    age=DAY-int(r['start_day']); e=eff(r['group_id'],r['plan'],r['listed_price'],age,r['promotion'])*int(r['seat_count'])
    mrr+=e; field+=float(r['effective_price'])*int(r['seat_count'])
    key=(r['group_id'],r['plan'],float(r['listed_price']),promo_for(r['group_id'],r['plan'],r['listed_price'],age,r['promotion']),'young' if age<61 else 'old')
    bym[key]=bym.get(key,[0,0.0])[0]+1, bym.get(key,[0,0.0])[1]+e
print('\nadj_mrr',mrr,'field_mrr',field)
for k,v in sorted(bym.items(), key=lambda kv: kv[1][1], reverse=True)[:40]: print(k,v)
# last week payments initial vs renewal totals
base=f"""from ledger l join customers c on c.customer_id=cast(substr(l.note,instr(l.note,'customer ')+9) as integer) join subscriptions s on s.customer_id=c.customer_id
where l.category='subscription_payment' and l.day>{DAY-7} and l.day<={DAY}"""
print('\npayments initial vs renewal last7:')
for r in q(f"""select case when l.day-s.start_day<2 then 'initial' else 'renewal' end kind, count(*) n, sum(l.amount) amt {base} group by kind"""):
    print(r)
print('\nnew starts last7 count by source/plan and actual initial amount assumption:')
for r in q(f"""select c.acquisition_source,s.plan,s.listed_price,count(*) n from subscriptions s join customers c using(customer_id) where s.status='subscribed' and s.start_day>{DAY-7} and s.start_day<={DAY} and c.group_id='S2' group by c.acquisition_source,s.plan,s.listed_price order by n desc"""):
    print(r)
# Ads performance daily
print('\nad leads daily last14')
for r in q(f"select day,sum(spend) spend,sum(leads_generated) leads from ad_channel_leads where day>{DAY-14} and day<={DAY} group by day order by day"):
    print(r)

