arguments.command:
./novamind-operation python-c "import novamind_api as nm; DAY=nm.vars.current_day; qs=[('issues opened last 14','SELECT open_day, COUNT(*) n FROM issues WHERE open_day>'+str(DAY-14)+' GROUP BY open_day ORDER BY open_day'),('issues resolved last14','SELECT resolved_day, COUNT(*) n FROM issues WHERE resolved_day>'+str(DAY-14)+' GROUP BY resolved_day ORDER BY resolved_day'),('active counts by day?','SELECT day, SUM(usage_units) usage, COUNT(*) rows FROM daily_usage WHERE day>'+str(DAY-14)+' GROUP BY day ORDER BY day')];
for name,q in qs:
 print('\n',name); 
 for r in nm.query(q)['rows']: print(r)"

./novamind-operation python-c "import novamind_api as nm; DAY=nm.vars.current_day; mod=DAY%30; expr=f'({DAY} + CASE WHEN ((billing_day_mod30 - {mod} + 30) % 30)=0 THEN 30 ELSE ((billing_day_mod30 - {mod} + 30) % 30) END)';
for horizon in [7,28,84,182]:
 q=f'''SELECT SUM(CASE WHEN {DAY}-s.start_day>=61 THEN s.effective_price ELSE 0 END) old_eff, SUM(CASE WHEN {DAY}-s.start_day<61 THEN s.effective_price ELSE 0 END) young_eff, COUNT(*) n, SUM(s.effective_price) eff FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' AND c.group_id='S2' AND {expr}>{DAY} AND {expr}<={DAY+horizon}'''
 print(horizon, nm.query(q)['rows'][0])"

