arguments.command:
./novamind-operation python-c "import novamind_api as nm; DAY=nm.vars.current_day; mod=DAY%30; expr=f'({DAY} + CASE WHEN ((billing_day_mod30 - {mod} + 30) % 30)=0 THEN 30 ELSE ((billing_day_mod30 - {mod} + 30) % 30) END)'; promo=f'''CASE WHEN c.group_id='D_S07' THEN 210 WHEN c.group_id='S3' THEN 120 WHEN c.group_id='S2' AND s.plan='C' AND s.listed_price=259 AND {DAY}-s.start_day<61 THEN 80 WHEN s.promotion>0 THEN s.promotion ELSE 0 END'''; rev=f'(s.listed_price - ({promo}))';
for horizon in [7,28,30]:
 q=f'''SELECT SUM(CASE WHEN {DAY}-s.start_day>=61 THEN {rev} ELSE 0 END) old_rev, SUM(CASE WHEN {DAY}-s.start_day<61 THEN {rev} ELSE 0 END) young_rev, SUM({rev}) total_rev, COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' AND {expr}>{DAY} AND {expr}<={DAY+horizon}'''
 print(horizon, nm.query(q)['rows'][0])
print('next7 detail'); rows=nm.query(f'''SELECT {expr} due_day, CASE WHEN {DAY}-s.start_day>=61 THEN 'old' ELSE 'young' END age, s.plan, s.listed_price, ({promo}) promo, COUNT(*) n, SUM({rev}) rev FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' AND {expr}>{DAY} AND {expr}<={DAY+7} GROUP BY 1,2,3,4,5 ORDER BY 1,2,rev DESC LIMIT 100''')['rows']; [print(r) for r in rows]"

