./novamind-operation python-c "import novamind_api as nm; DAY=nm.vars.current_day; queries=[('acq day 280-308 by status', '''SELECT s.start_day, c.acquisition_source, s.status, s.plan, s.listed_price, COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.group_id=\"S2\" AND s.start_day BETWEEN 280 AND 329 GROUP BY 1,2,3,4,5 ORDER BY 1,2,3,4'''), ('customers created 280-329 source', '''SELECT created_day, acquisition_source, COUNT(*) n FROM customers WHERE group_id=\"S2\" AND created_day BETWEEN 280 AND 329 GROUP BY 1,2 ORDER BY 1,2''')];
for name,sql in queries:
 print('##',name); rows=nm.query(sql)['rows'];
 for r in rows[:300]: print(r)
 print('rows',len(rows))" > acq_day329.out 2>&1; sed -n '1,260p' acq_day329.out

