import novamind_api as nm, json, math

def q(sql):
    r=nm.query(sql)
    return r['rows']
print('day', nm.vars.current_day)
# cash ledger
rows=q("SELECT SUM(amount) as cash FROM ledger")
print('cash', rows)
# ledger weekly by type/category columns? Let's see schema maybe print cols? use select * limit 3
try:
    rows=q("SELECT * FROM ledger ORDER BY day DESC LIMIT 10")
    print('ledger sample')
    for r in rows: print(r)
except Exception as e: print('ledger sample err', e)
# weekly sums by day/type/description maybe
try:
    rows=q("SELECT day, category, description, SUM(amount) as amt, COUNT(*) as n FROM ledger WHERE day>357 GROUP BY day, category, description ORDER BY day, category, description")
    print('\nledger since day357')
    for r in rows: print(r)
except Exception as e: print('weekly ledger group err', e)
try:
    rows=q("SELECT category, SUM(amount) as amt, COUNT(*) as n FROM ledger WHERE day>357 GROUP BY category ORDER BY amt")
    print('\nledger since day357 by category')
    for r in rows: print(r)
except Exception as e: print('weekly category err', e)
# subs status counts
for sql in [
"SELECT status, COUNT(*) n FROM subscriptions GROUP BY status",
"SELECT c.group_id, s.plan, COUNT(*) n, SUM(COALESCE(c.seat_count,1)) seats, AVG(s.listed_price) avg_list, AVG(s.effective_price) avg_eff, SUM(s.listed_price) sum_list, SUM(s.effective_price) sum_eff FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status='subscribed' GROUP BY c.group_id,s.plan ORDER BY c.group_id,s.plan",
"SELECT c.group_id, COUNT(*) n, SUM(s.listed_price) list_mrr, SUM(s.effective_price) eff_mrr, MIN(s.next_billing_day) min_due, MAX(s.next_billing_day) max_due FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status='subscribed' GROUP BY c.group_id ORDER BY n DESC"
]:
    try:
        print('\nSQL:', sql)
        for r in q(sql): print(r)
    except Exception as e: print('err',e)
# upcoming bills next 30 by day and plan/list price/promo buckets
try:
    rows=q("SELECT s.next_billing_day, s.plan, ROUND(s.listed_price,0) as list, ROUND(s.promotion,0) promo, COUNT(*) n, SUM(s.effective_price) eff_mrr, SUM(s.listed_price) list_mrr FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status='subscribed' AND s.next_billing_day BETWEEN 365 AND 394 GROUP BY s.next_billing_day,s.plan,ROUND(s.listed_price,0),ROUND(s.promotion,0) ORDER BY s.next_billing_day,s.plan,list,promo")
    print('\nUpcoming bills detail 365-394')
    for r in rows[:200]: print(r)
except Exception as e: print('upcoming detail err',e)
try:
    rows=q("SELECT s.next_billing_day, COUNT(*) n, SUM(s.effective_price) eff, SUM(s.listed_price) list, AVG(s.effective_price) avg_eff FROM subscriptions s WHERE s.status='subscribed' AND s.next_billing_day BETWEEN 365 AND 394 GROUP BY s.next_billing_day ORDER BY s.next_billing_day")
    print('\nUpcoming due by day 365-394')
    for r in rows: print(r)
except Exception as e: print('upcoming err',e)
# cancellations since 357: maybe subscriptions status canceled with cancellation_day?
try:
    rows=q("SELECT * FROM subscriptions WHERE status!='subscribed' ORDER BY end_day DESC LIMIT 5")
    print('\ncanceled sample')
    for r in rows: print(r)
except Exception as e: print('canceled sample err',e)
try:
    rows=q("SELECT end_day, plan, ROUND(listed_price,0) list, ROUND(promotion,0) promo, COUNT(*) n, SUM(effective_price) eff, SUM(listed_price) list_sum FROM subscriptions WHERE status!='subscribed' AND end_day>357 GROUP BY end_day,plan,ROUND(listed_price,0),ROUND(promotion,0) ORDER BY end_day,plan,list,promo")
    print('\ncancellations since 357')
    for r in rows[:200]: print(r)
except Exception as e: print('cancel group err',e)
# payments since 357 by plan/list maybe ledger maybe customer_id accessible? sample above first.
# issues schema/sample/status
try:
    rows=q("SELECT * FROM issues ORDER BY open_day DESC LIMIT 10")
    print('\nissues sample')
    for r in rows: print(r)
except Exception as e: print('issues sample err',e)
try:
    rows=q("SELECT i.status, COUNT(*) n, MIN(i.open_day) min_open, MAX(i.open_day) max_open, AVG(i.days_open) avg_days, MAX(i.days_open) max_days FROM issues i GROUP BY i.status")
    print('\nissues by status all')
    for r in rows: print(r)
except Exception as e: print('issues status err',e)
try:
    rows=q("SELECT i.status, c.group_id, COUNT(*) n, MIN(i.open_day) min_open, MAX(i.open_day) max_open, AVG(i.days_open) avg_days, MAX(i.days_open) max_days FROM issues i JOIN customers c ON i.customer_id=c.customer_id WHERE EXISTS (SELECT 1 FROM subscriptions s WHERE s.customer_id=i.customer_id AND s.status='subscribed') GROUP BY i.status,c.group_id ORDER BY i.status,c.group_id")
    print('\nissues active-customer by status/group')
    for r in rows: print(r)
except Exception as e: print('issues active err',e)
try:
    rows=q("SELECT open_day, status, COUNT(*) n, AVG(days_open) avg_days, MAX(days_open) max_days FROM issues WHERE EXISTS (SELECT 1 FROM subscriptions s WHERE s.customer_id=issues.customer_id AND s.status='subscribed') GROUP BY open_day,status ORDER BY open_day DESC,status LIMIT 30")
    print('\nactive-customer issues by open day')
    for r in rows: print(r)
except Exception as e: print('issues by day err',e)
# usage daily last 14? table metrics? Need schemas list? use sqlite? query not direct maybe table name daily_metrics? try
for table in ['daily_metrics','metrics','events','outages']:
    try:
        rows=q(f"SELECT * FROM {table} ORDER BY day DESC LIMIT 5")
        print('\n',table)
        for r in rows: print(r)
    except Exception as e: pass
# enterprise open turns latest
try:
    rows=q("SELECT * FROM enterprise_turns WHERE closed=0 ORDER BY day DESC, message_id DESC LIMIT 20")
    print('\nopen enterprise turns')
    for r in rows: print(r)
except Exception as e: print('ent err', e)
# social posts recent
try:
    posts=nm.analytics.get_social_posts(days=14, limit=50)
    print('\nsocial posts 14d')
    print(json.dumps(posts, indent=2)[:6000])
except Exception as e: print('social err', e)
# market overview maybe includes groups expected? cost_info research projects config
try:
    print('\ncost info')
    print(json.dumps(nm.infrastructure.get_cost_info(), indent=2)[:4000])
except Exception as e: print('cost err',e)
try:
    print('\nresearch projects')
    print(json.dumps(nm.research.list_research_projects(), indent=2)[:4000])
except Exception as e: print('research err',e)
