import novamind_api as nm, json
q=lambda sql:nm.query(sql)['rows']
# settings history last 80 days truncated
for table in ['settings','config_changes','tool_invocations']:
    try:
        rows=q(f"SELECT * FROM {table} ORDER BY day DESC LIMIT 10")
        print('TABLE',table)
        for r in rows[:3]: print(r)
    except Exception as e: print('no',table,e)
print('settings ops/dev recent')
try:
 for r in q("SELECT id,day,tool_name,setting_type,SUBSTR(settings_json,1,500) settings_prefix FROM settings WHERE day>=300 ORDER BY day,id"):
    if any(x in str(r) for x in ['ops','dev','model','promotion','price','capacity']):
        print(r)
except Exception as e: print('settings err',e)
# weekly metrics by 7d periods since 300
print('weekly ledger since 300')
for start in range(301,365,7):
    end=start+6
    row=q(f"SELECT SUM(CASE WHEN amount>0 THEN amount ELSE 0 END) rev, SUM(CASE WHEN amount<0 THEN amount ELSE 0 END) cost, SUM(amount) net FROM ledger WHERE day BETWEEN {start} AND {end}")[0]
    cats=q(f"SELECT category, SUM(amount) amt FROM ledger WHERE day BETWEEN {start} AND {end} GROUP BY category ORDER BY category")
    canc=q(f"SELECT COUNT(*) n, SUM(effective_price) eff FROM subscriptions WHERE status='cancelled' AND end_day BETWEEN {start} AND {end}")[0]
    opens=q(f"SELECT COUNT(*) n, AVG(days_open) avg_days, MAX(days_open) max_days FROM issues WHERE status='open' AND open_day BETWEEN {start} AND {end}")[0]
    active_open=q(f"SELECT COUNT(*) n, MIN(open_day) min_open, AVG(days_open) avg_days, MAX(days_open) max_days FROM issues i WHERE i.status='open' AND EXISTS(SELECT 1 FROM subscriptions s WHERE s.customer_id=i.customer_id AND s.status='subscribed')")[0]
    print('\nweek',start,end,'ledger',row,'cancels',canc)
    for c in cats: print(' ',c)
PY
