cat > week54_issues_social.py <<'PY'
import novamind_api as nm
from pprint import pprint
cur=nm.vars.current_day
queries=[
("all_open", "SELECT COUNT(*) n, MAX(days_open) max_age, AVG(days_open) avg_age FROM issues WHERE status='open'"),
("open_by_age_all", "SELECT days_open, COUNT(*) n FROM issues WHERE status='open' GROUP BY days_open ORDER BY days_open LIMIT 20"),
("open_by_age_active", "SELECT i.days_open, COUNT(*) n FROM issues i WHERE i.status='open' AND EXISTS (SELECT 1 FROM subscriptions s WHERE s.customer_id=i.customer_id AND s.status='subscribed') GROUP BY i.days_open ORDER BY i.days_open LIMIT 20"),
("opened_recent", f"SELECT open_day, COUNT(*) opened, SUM(CASE WHEN status='resolved' THEN 1 ELSE 0 END) resolved, SUM(CASE WHEN status='open' THEN 1 ELSE 0 END) still_open, AVG(COALESCE(resolved_day,{cur})-open_day) avg_age_now FROM issues WHERE open_day>371 GROUP BY open_day ORDER BY open_day"),
("resolved_recent", "SELECT resolved_day, COUNT(*) n, AVG(resolved_day-open_day) avg_resolution_days, MAX(resolved_day-open_day) max_res_days FROM issues WHERE resolved_day>371 GROUP BY resolved_day ORDER BY resolved_day"),
("old_open_groups", "SELECT group_id, COUNT(*) n, MIN(open_day) min_open, MAX(open_day) max_open, AVG(days_open) avg_age FROM issues WHERE status='open' AND days_open>0 GROUP BY group_id ORDER BY n DESC LIMIT 20"),
]
for name,sql in queries:
    print('\n--',name)
    try:
        for r in nm.query(sql)['rows']: print(r)
    except Exception as e: print('ERR',e)
print('\n-- social last 7d limit 20')
try:
    res=nm.analytics.get_social_posts(days=7, limit=20)
    print('total', res.get('total') if isinstance(res,dict) else None)
    posts=res['posts'] if isinstance(res,dict) and 'posts' in res else res
    for p in posts[:20]:
        print('post',p.get('post_id'),'day',p.get('day'),'group',p.get('group_id'),'src',p.get('source_group_id'),'reply?', bool(p.get('reply_to_agent_post_id')))
        print(p.get('content'))
        if p.get('replying_to_your_post'): print('  reply_to:', p.get('replying_to_your_post')[:120])
except Exception as e: print('ERR',e)
print('\n-- recent competitor-ish posts')
try:
    res=nm.analytics.get_social_posts(days=21, limit=100)
    posts=res['posts'] if isinstance(res,dict) and 'posts' in res else res
    for p in posts:
        c=p.get('content','').lower()
        if any(w in c for w in ['competitor','rival','launched','launch','announced','benchmark','model','latency','quality','outage','bug','ticket','support']):
            print('post',p.get('post_id'),'day',p.get('day'),'group',p.get('group_id'),'src',p.get('source_group_id'),':',p.get('content')[:250])
except Exception as e: print('ERR',e)
PY
