./novamind-operation python-c "import novamind_api as nm;cur=nm.vars.current_day;curmod=cur%30
for h in [7,14,21,28]:
 print('h',h)
 sql=f'''SELECT listed_price,promotion,effective_price, COUNT(*) n, SUM(effective_price*seat_count) due FROM subscriptions WHERE status='subscribed' AND (CASE WHEN ((billing_day_mod30 - {curmod} + 30) % 30)=0 THEN 30 ELSE ((billing_day_mod30 - {curmod} + 30) % 30) END)<={h} GROUP BY listed_price,promotion,effective_price ORDER BY due DESC'''
 for r in nm.query(sql)['rows']: print(r)
" | sed -n '1,200p'

