    show('social_media_posts raw recent', q(f"SELECT post_id, day, content FROM social_media_posts WHERE day>{DAY-14} ORDER BY day DESC, post_id DESC LIMIT 100"), 100)
except Exception as e: print('social table err', e)
try:
    show('agent social posts recent', q(f"SELECT * FROM agent_social_media_posts WHERE day>{DAY-30} ORDER BY day DESC LIMIT 20"), 20)
except Exception as e: print('agent table err',e)
show('enterprise open', q("SELECT customer_id, day, sender, status, closed, message_text FROM enterprise_turns WHERE closed=0 ORDER BY day DESC LIMIT 20"), 20)
print('\n-- research --')
r=nm.research.list_research_projects()
print(r)

