import novamind_api as nm
DAY=nm.vars.current_day
rows=nm.query("SELECT customer_id,start_day,billing_day_mod30,listed_price,promotion,effective_price,seat_count FROM subscriptions WHERE status='subscribed'")['rows']
def adj_eff(r):
    lp=r['listed_price']; promo=r['promotion'] or 0
    target=None
    if r['start_day']>=100:
        target=89
    elif 73<=r['start_day']<100:
        target=99
    if target is None:
        return r['effective_price']
    desired_promo=max(promo, lp-target)
    return max(0, lp-desired_promo)
for h in [7,14,21,28,30,35,56,84,91]:
    total=0; roweff=0; n=0
    mods=[(DAY+i)%30 for i in range(1,h+1)]
    counts={m:mods.count(m) for m in set(mods)}
    for r in rows:
        cnt=counts.get(r['billing_day_mod30'],0)
        if cnt:
            n += cnt
            total += cnt*adj_eff(r)*r['seat_count']
            roweff += cnt*r['effective_price']*r['seat_count']
    print(h,n,roweff,total)
for i in range(1,31):
    mod=(DAY+i)%30
    due=sum(adj_eff(r)*r['seat_count'] for r in rows if r['billing_day_mod30']==mod)
    due_old=sum(r['effective_price']*r['seat_count'] for r in rows if r['billing_day_mod30']==mod)
    n=sum(1 for r in rows if r['billing_day_mod30']==mod)
    print('day',DAY+i,'mod',mod,'n',n,'old',due_old,'adj',due)
# by start buckets next14 adjusted
for h in [7,14,28,30]:
    mods=[(DAY+i)%30 for i in range(1,h+1)]
    counts={m:mods.count(m) for m in set(mods)}
    buckets={}
    for r in rows:
        cnt=counts.get(r['billing_day_mod30'],0)
        if cnt:
            b=(r['start_day']//10)*10
            if b not in buckets: buckets[b]=[0,0,0]
            buckets[b][0]+=cnt; buckets[b][1]+=cnt*r['effective_price']; buckets[b][2]+=cnt*adj_eff(r)
    print('\nH',h)
    for b,v in sorted(buckets.items()): print(b,v)

import novamind_api as nm
DAY=nm.vars.current_day
rows=[]; last=-1
while True:
    batch=nm.query(f"SELECT customer_id,start_day,billing_day_mod30,listed_price,promotion,effective_price,seat_count FROM subscriptions WHERE status='subscribed' AND customer_id>{last} ORDER BY customer_id LIMIT 5000")['rows']
    if not batch: break
    rows.extend(batch); last=batch[-1]['customer_id']
print('rows',len(rows),'last',last)
def adj_eff(r):
    lp=r['listed_price']; promo=r['promotion'] or 0
    target=None
    if r['start_day']>=100:
        target=89
    elif 73<=r['start_day']<100:
        target=99
    if target is None:
        return r['effective_price']
    desired_promo=max(promo, lp-target)
    return max(0, lp-desired_promo)
for h in [7,14,21,28,30,35,56,84,91]:
    total=0; roweff=0; n=0; listdue=0
    mods=[(DAY+i)%30 for i in range(1,h+1)]
    counts={m:mods.count(m) for m in set(mods)}
    for r in rows:
        cnt=counts.get(r['billing_day_mod30'],0)
        if cnt:
            n += cnt
