import novamind_api as nm, json
DAY=nm.vars.current_day
prom=json.loads(nm.query("SELECT settings_json FROM config_overrides WHERE setting_type='promotion' ORDER BY id DESC LIMIT 1")['rows'][0]['settings_json'])
bycust=prom.get('by_customer',{})
print('prom counts', len(bycust), 'global', prom.get('global'), 'by_group', prom.get('by_group'))
rows=[]; last=-1
while True:
    b=nm.query(f"SELECT customer_id,start_day,billing_day_mod30,listed_price,promotion,effective_price,seat_count FROM subscriptions WHERE status='subscribed' AND customer_id>{last} ORDER BY customer_id LIMIT 5000")['rows']
    if not b: break
    rows+=b; last=b[-1]['customer_id']
print('active',len(rows))
def cfg_eff(r):
    p=(prom.get('global') or 0) + (prom.get('by_group',{}).get('S2',0) or 0) + (bycust.get(str(r['customer_id']),0) or 0)
    return max(0, r['listed_price']-p)
# compare actual config vs rule
for h in [7,14,28,30,56,84,91]:
    mods=[(DAY+i)%30 for i in range(1,h+1)]; counts={m:mods.count(m) for m in set(mods)}
    sums=[0,0,0]; bills=0
    for r in rows:
        c=counts.get(r['billing_day_mod30'],0)
        if c:
            bills+=c; sums[0]+=c*r['effective_price']; sums[1]+=c*cfg_eff(r); sums[2]+=c*r['listed_price']
    print('h',h,'bills',bills,'roweff',sums[0],'cfg_eff',sums[1],'list',sums[2])
for i in range(1,31):
    m=(DAY+i)%30; subset=[r for r in rows if r['billing_day_mod30']==m]
    print(DAY+i,len(subset),sum(r['effective_price'] for r in subset),sum(cfg_eff(r) for r in subset))
# active not in map start>=100 or 73-99?
miss=[]
for r in rows:
    has=str(r['customer_id']) in bycust
    if ((r['start_day']>=100) or (73<=r['start_day']<100)) and not has:
        miss.append(r)
print('miss targeted count',len(miss),'sample',miss[:10])

