./novamind-operation python-c "import novamind_api as nm; q=lambda s:nm.query(s)['rows'];
for d in range(351,358):
 rows=q(f'''SELECT ROUND(effective_price,2) ep, COUNT(*) n, ROUND(SUM(effective_price),2) mrr FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.group_id=\"S2\" AND s.status=\"cancelled\" AND s.end_day={d} GROUP BY ROUND(effective_price,2) ORDER BY ep'''); print('day',d,rows[:20], 'total', sum(r['n'] for r in rows), sum(r['mrr'] or 0 for r in rows))"

./novamind-operation python-c "import novamind_api as nm; q=lambda s:nm.query(s)['rows'];
for start,end in [(120,140),(90,120),(280,300),(336,365)]:
 print('range',start,end); rows=q(f'''SELECT d.day, (SELECT SUM(-amount) FROM ledger WHERE day=d.day AND category=\"operations\") ops, (SELECT COUNT(*) FROM subscriptions WHERE status=\"subscribed\" AND start_day<=d.day AND (end_day IS NULL OR end_day>d.day)) active_now_approx, (SELECT COUNT(*) FROM issues WHERE open_day=d.day AND group_id=\"S2\") opened, (SELECT COUNT(*) FROM issues WHERE resolved_day=d.day AND group_id=\"S2\") resolved, (SELECT COUNT(*) FROM subscriptions WHERE status=\"cancelled\" AND end_day=d.day) canc FROM (SELECT DISTINCT day FROM ledger WHERE day BETWEEN {start} AND {end}) d ORDER BY d.day''');
 for r in rows[:25]: print(r); print()" | head -260

