arguments.command:
./novamind-operation python-c "import novamind_api as nm; q=lambda s:nm.query(s)['rows']; cur=nm.vars.current_day;
# usage distribution active subs last 7 per customer/day
for threshold in [250,500,750,1000,1500,2000]:
 r=q(f'''SELECT COUNT(*) n, SUM(usage_units) units FROM daily_usage du JOIN subscriptions s ON s.customer_id=du.customer_id WHERE s.status=\"subscribed\" AND du.day>{cur-7} AND du.usage_units>{threshold}''')[0]; print('>',threshold,r)
print('percentiles approx by day last 7')
for d in range(cur-6,cur+1):
 rows=q(f'''SELECT usage_units, COUNT(*) n FROM daily_usage du JOIN subscriptions s ON s.customer_id=du.customer_id WHERE s.status=\"subscribed\" AND du.day={d} GROUP BY usage_units ORDER BY usage_units''')
 total=sum(r['n'] for r in rows); cum=0; vals={};
 for r in rows:
  cum+=r['n'];
  for p in [0.5,0.75,0.9,0.95,0.99,0.999]:
   if p not in vals and cum>=p*total: vals[p]=r['usage_units']
 print(d,'total',total,'sum',sum(r['usage_units']*r['n'] for r in rows),'pct',vals,'max',rows[-1]['usage_units'] if rows else None)
"

./novamind-operation python-c "import novamind_api as nm; q=lambda s:nm.query(s)['rows']; cur=nm.vars.current_day;
for cap in [600,500,400,350,300,250,200,150]:
 r=q(f'''SELECT COUNT(*) n, SUM(CASE WHEN usage_units>{cap} THEN usage_units-{cap} ELSE 0 END) save, SUM(usage_units) total FROM daily_usage du JOIN subscriptions s ON s.customer_id=du.customer_id WHERE s.status=\"subscribed\" AND du.day>{cur-7}''')[0]
 print(cap,r,'C4_save_$', (r['save'] or 0)*0.012)
"

